import{_ as e,o as r,c as i,ai as l}from"./chunks/framework.ETupdKIa.js";const _=JSON.parse('{"title":"コンピューター間通信のフロー","description":"","frontmatter":{},"headers":[],"relativePath":"til/network/コンピューター間通信のフロー.md","filePath":"til/network/コンピューター間通信のフロー.md"}'),t={name:"til/network/コンピューター間通信のフロー.md"};function n(h,a,o,s,P,d){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="コンピューター間通信のフロー" tabindex="-1">コンピューター間通信のフロー <a class="header-anchor" href="#コンピューター間通信のフロー" aria-label="Permalink to “コンピューター間通信のフロー”">​</a></h1><h2 id="フローの全体像" tabindex="-1">フローの全体像 <a class="header-anchor" href="#フローの全体像" aria-label="Permalink to “フローの全体像”">​</a></h2><ol><li>ソケット作成</li><li>コネクションの確立</li><li>データ送受信</li><li>コネクションの破棄</li></ol><h2 id="ソケット作成" tabindex="-1">ソケット作成 <a class="header-anchor" href="#ソケット作成" aria-label="Permalink to “ソケット作成”">​</a></h2><p>browserなどのアプリケーションがSocketライブラリ経由でOSのプロトコルスタックにソケット作成を依頼する。 ソケットとは、プロトコルスタック内のメモリ領域のことを指し、通信に必要な制御情報（クライアントのIP、サーバーのIP、クライアント-サーバー間の通信状態（未接続なのか、接続済みなのか、など）、通信しようとしているプロセスのIDなど）が記録される。 ソケット作成とは、プロトコルスタックがこのメモリ領域を確保することを指す。 ソケット作成後は、アプリケーションに制御が戻る。</p><h2 id="コネクションの確立" tabindex="-1">コネクションの確立 <a class="header-anchor" href="#コネクションの確立" aria-label="Permalink to “コネクションの確立”">​</a></h2><p>アプリケーションがSocketライブラリのconnect()関数を呼び出すと、プロトコルスタックがコネクション確立を開始する。 アプリケーションはプロトコルスタックに、接続先のIPアドレスを渡す。 プロトコルスタックはサーバーに対し、接続元/接続先のIP・ポート番号を含むパケットを送信する。 サーバーはパケットを受領し接続処理を行った上で、「パケットを受領したこと」を示す情報を含むパケットをクライアントに送信する。 クライアントはパケットを受領し、ソケットに接続先IP・ポートを記録した上で、「パケットを受領したこと」を示す情報を含むパケットをサーバーに送信し、アプリケーションに制御が戻る。 サーバーはパケットを受領し、コネクションの確立が完了する。</p><p>↑これが「3wayhandshake」と言われる手順？</p><h2 id="データの送受信" tabindex="-1">データの送受信 <a class="header-anchor" href="#データの送受信" aria-label="Permalink to “データの送受信”">​</a></h2><h3 id="パケットの送信" tabindex="-1">パケットの送信 <a class="header-anchor" href="#パケットの送信" aria-label="Permalink to “パケットの送信”">​</a></h3><p>アプリケーションはSocketライブラリのwrite(descriptor, request-message)を呼び出し、プロトコルスタックにデータの送受信を依頼する。 プロトコルスタックが一度に送信できるデータ量は決まっている（maximum transfer unit, maximum segment size）。 データ送信効率を高めるために、MSSギリギリになるまでアプリケーションからの送信依頼を溜め、一回の送信でなるべく多くのデータを送信しようとする。 しかし、MSSギリギリまでデータ送信を待つと、アプリケーションからの送信依頼から実際の送信までにタイムラグが生じる。そのため待ち時間の限度もプロトコルスタックで決まっている。 また、アプリケーションから渡されたリクエストメッセージのサイズがMSSより大きい場合は、TCPがMSSに収まるようにリクエストメッセージを分割する。</p><h3 id="受信確認応答" tabindex="-1">受信確認応答 <a class="header-anchor" href="#受信確認応答" aria-label="Permalink to “受信確認応答”">​</a></h3><p>TCPでは送信したパケットが相手に届いたかどうかを検証する。 送信側は送信対象のデータをパケットに分割し、各パケットが先頭から何バイト目なのかを計算する。この値をシーケンス番号と言う。 パケット送信時は、送信対象のパケットのシーケンス番号がTCPヘッダに付加される。 受信側はパケットとシーケンス番号を受け取る。パケットサイズを計算し、ACK番号として「シーケンス番号+パケットサイズ」を送信側に返却する（受信応答確認）。 送信側はACK番号を確認し、パケットが相手に届いたことを確認する。</p><h3 id="ウィンドウサイズ" tabindex="-1">ウィンドウサイズ <a class="header-anchor" href="#ウィンドウサイズ" aria-label="Permalink to “ウィンドウサイズ”">​</a></h3><p>受信側は、受け取ったパケットを受信バッファに溜めた上でACK番号の計算等の処理を行い、データをアプリケーションに渡すと、その分の受信バッファを解放する。 受信バッファのサイズを超えてパケットが送信されてきた場合、その分は受信バッファに溜められず消滅する。受信バッファのサイズをウィンドウサイズと呼ぶ。 一方、送信側はACK番号の返却を待たずに次々とパケットを送信したいが、受信側のバッファを超えないように気をつける必要がある。 送信側が「あとどのくらいパケットを送信できるか」がわかるよう、受信側はバッファの空き容量をTCPヘッダのウィンドウフィールドにセットし、送信側に連携する。</p><h2 id="ip-イーサネット層の役割" tabindex="-1">IP,イーサネット層の役割 <a class="header-anchor" href="#ip-イーサネット層の役割" aria-label="Permalink to “IP,イーサネット層の役割”">​</a></h2><ul><li>クライアントでパケット作成時にIPヘッダ、MACヘッダが作成される。</li><li>宛先に向かう途中で複数個のルーターを経由するが、ルーターを経由する度にMACヘッダーのMACアドレスが次に向かうルーターの値に書き変わる。</li></ul><h3 id="ipヘッダ、macヘッダの作成" tabindex="-1">IPヘッダ、MACヘッダの作成 <a class="header-anchor" href="#ipヘッダ、macヘッダの作成" aria-label="Permalink to “IPヘッダ、MACヘッダの作成”">​</a></h3><p>IPはTCPからパケット送信依頼を受ける。 IPは、初めにIPヘッダを作成する。宛先IPはTCPから受け取ったものをセットし、送信元IPはクライアントが持つ経路表からセットする値を探す。 ※そもそもIPアドレスはマシンごとに決まる値ではなく、LANアダプタごとに決まる値である。１つのマシンが複数のLANアダプタを持つ場合、すなわち１つのマシンが複数のIPアドレスを持つことになり、送信元IPアドレスにどれをセットすべきか明らかではない。経路表では「宛先IPアドレス」「次に経由すべきルーター」「送信元IP」の組画管理されており、TCPから受け取った宛先IPを使い、「送信元IP」を特定する。 IPヘッダを作成したら、次にMACヘッダを作成する。MACヘッダには送信元MACアドレスや宛先MACアドレスをセットする。宛先MACアドレスは次に経由するルーターのMACアドレスをセットすることになっており、ARPを使い値を取得する。</p>',19)])])}const p=e(t,[["render",n]]);export{_ as __pageData,p as default};
